+/* ============ Tokens ============ */
+:root {
+  --bg: #faf8f5;
+  --surface: #ffffff;
+  --ink: #14130f;
+  --ink-2: #3a3833;
+  --muted: #76726a;
+  --line: #e9e4dc;
+  --line-2: #d9d3c7;
