+.deal--lg .deal__content h3 { font-size: clamp(1.6rem, 2.6vw, 2.2rem); }
+.deal__content p { color: rgba(255,255,255,.85); font-size: .92rem; }
+.deal__content .link-arrow { color: #fff; margin-top: 6px; align-self: flex-start; }
+.deal__content .link-arrow:hover { color: #fff; opacity: .85; }
+
+.badge {
+  align-self: flex-start;
+  background: rgba(255,255,255,.15);
+  border: 1px solid rgba(255,255,255,.3);
+  backdrop-filter: blur(8px);
+  padding: 5px 12px;
+  border-radius: 999px;
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+}
+.badge--accent { background: var(--accent); border-color: transparent; }
+.badge--dark   { background: var(--ink); border-color: transparent; }
+
+.deal-bg-1 { background-image: url('https://images.unsplash.com/photo-1539109136881-3be0616acf4b?w=1200&q=80'); background-color: #6b5d4a; }
+.deal-bg-2 { background-image: url('https://images.unsplash.com/photo-1576566588028-4147f3842f27?w=800&q=80'); background-color: #8a7560; }
+.deal-bg-3 { background-image: url('https://images.unsplash.com/photo-1487222477894-8943e31ef7b2?w=800&q=80'); background-color: #5a4a3a; }
+.deal-bg-4 { background-image: url('https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=1400&q=80'); background-color: #7a6a55; }
+
+@media (max-width: 880px) {
+  .deals__grid {
+    grid-template-columns: 1fr 1fr;
+    grid-template-rows: 280px 200px 200px;
+  }
+  .deal--lg { grid-row: span 1; grid-column: span 2; }
+  .deal--wide { grid-column: span 2; }
+}
+
+/* ============ Editorial ============ */
+.editorial { padding: 88px 0; background: var(--bg); }
+.editorial__grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 28px;
+}
+.story {
+  display: flex; flex-direction: column;
+  gap: 16px;
+}
+.story--feature {
+  grid-row: span 2;
+}
+.story__media {
+  display: block;
+  aspect-ratio: 4/5;
+  border-radius: var(--radius);
+  background-size: cover;
+  background-position: center;
+  overflow: hidden;
+  background-color: var(--sand);
+  transition: transform var(--t);
+}
+.story:not(.story--feature) .story__media { aspect-ratio: 16/10; }
+.story__media:hover { transform: translateY(-3px); }
+
+.story-media-1 { background-image: linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.2)), url('https://images.unsplash.com/photo-1558769132-cb1aea458c5e?w=1000&q=80'); }
+.story-media-2 { background-image: linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.2)), url('https://images.unsplash.com/photo-1551803091-e20673f15770?w=800&q=80'); }
+.story-media-3 { background-image: linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.2)), url('https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=800&q=80'); }
+.story-media-4 { background-image: linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.2)), url('https://images.unsplash.com/photo-1542838132-92c53300491e?w=800&q=80'); }
+
+.story__tag {
+  display: inline-block;
+  font-size: .72rem;
+  text-transform: uppercase;
+  letter-spacing: .12em;
+  font-weight: 600;
+  color: var(--accent);
+}
+.story h3 {
+  font-size: 1.15rem;
+  line-height: 1.3;
+}
+.story--feature h3 { font-size: 1.6rem; }
+.story h3 a { background-image: linear-gradient(currentColor, currentColor); background-size: 0% 1px; background-repeat: no-repeat; background-position: 0 100%; transition: background-size var(--t); }
+.story h3 a:hover { background-size: 100% 1px; }
+.story__meta { color: var(--muted); font-size: .82rem; display: flex; gap: 8px; flex-wrap: wrap; }
+.story__body { display: flex; flex-direction: column; gap: 8px; }
+.story__body p { font-size: .95rem; }
+
+@media (max-width: 980px) {
+  .editorial__grid { grid-template-columns: 1fr 1fr; }
+  .story--feature { grid-column: span 2; grid-row: span 1; }
+}
+@media (max-width: 600px) {
+  .editorial__grid { grid-template-columns: 1fr; }
+  .story--feature { grid-column: span 1; }
+}
+
+/* ============ Values ============ */
+.values { padding: 56px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
+.values__grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 32px;
+}
+.value { display: flex; flex-direction: column; gap: 8px; }
+.value svg { color: var(--accent); }
+.value h4 { font-family: 'Inter', sans-serif; font-size: 1rem; font-weight: 600; }
+.value p { font-size: .88rem; color: var(--muted); }
+
+@media (max-width: 780px) {
+  .values__grid { grid-template-columns: repeat(2, 1fr); }
+}
+
+/* ============ Newsletter ============ */
+.newsletter {
+  padding: 80px 0;
+  background: var(--cream);
+}
+.newsletter__inner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 48px;
+  align-items: center;
+}
+.newsletter__copy h2 { margin-bottom: 12px; }
+.newsletter__copy .eyebrow { color: var(--accent); }
+.newsletter__copy p { font-size: 1.02rem; max-width: 42ch; }
+
+.newsletter__form {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 8px;
+  position: relative;
+}
+.newsletter__form input {
+  height: 56px;
+  padding: 0 22px;
+  border: 1px solid var(--line-2);
+  background: #fff;
+  border-radius: 999px;
+  font-size: 1rem;
+  color: var(--ink);
+  transition: border-color var(--t), box-shadow var(--t);
+}
+.newsletter__form input:focus {
+  outline: 0;
+  border-color: var(--ink);
+  box-shadow: 0 0 0 4px rgba(20,19,15,.06);
+}
+.newsletter__form .btn { height: 56px; padding: 0 28px; }
+.newsletter__msg {
+  position: absolute; left: 22px; top: calc(100% + 8px);
+  font-size: .82rem;
+  color: var(--accent-2);
+}
+
+@media (max-width: 780px) {
+  .newsletter__inner { grid-template-columns: 1fr; gap: 28px; }
+  .newsletter__form { grid-template-columns: 1fr; }
+}
+
+/* ============ Footer ============ */
+.footer {
+  background: var(--ink);
+  color: #ddd5c5;
+  padding: 64px 0 28px;
+}
+.footer__grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr 1fr;
+  gap: 40px;
+  padding-bottom: 40px;
+  border-bottom: 1px solid rgba(255,255,255,.1);
+}
+.footer__brand p { color: rgba(255,255,255,.6); margin-top: 12px; max-width: 32ch; font-size: .92rem; }
+.footer h5 { font-family: 'Inter', sans-serif; font-size: .82rem; letter-spacing: .14em; text-transform: uppercase; color: #fff; margin-bottom: 16px; }
+.footer ul li { margin-bottom: 10px; }
+.footer ul a { font-size: .92rem; color: rgba(255,255,255,.7); transition: color var(--t); }
+.footer ul a:hover { color: #fff; }
+.footer__bar {
+  display: flex; justify-content: space-between; gap: 16px;
+  padding-top: 24px; flex-wrap: wrap;
+}
+.footer__bar small { color: rgba(255,255,255,.5); font-size: .78rem; }
+
+@media (max-width: 780px) {
+  .footer__grid { grid-template-columns: 1fr 1fr; }
+  .footer__brand { grid-column: span 2; }
+}
+
+/* ============ Toast ============ */
+.toast {
+  position: fixed;
+  bottom: 28px; left: 50%;
+  transform: translateX(-50%) translateY(80px);
+  background: var(--ink);
+  color: #fff;
+  padding: 14px 20px;
+  border-radius: 12px;
+  font-size: .9rem;
+  font-weight: 500;
+  box-shadow: var(--shadow-lg);
+  opacity: 0;
+  transition: transform var(--t), opacity var(--t);
+  z-index: 100;
+  pointer-events: none;
+}
+.toast.is-visible {
+  opacity: 1;
+  transform: translateX(-50%) translateY(0);
+}
+
+/* ============ Reduced motion ============ */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: 0.01ms !important;
+    transition-duration: 0.01ms !important;
+  }
+  .announcement__track { animation: none; padding-left: 0; }
+}
+
