          </div>
          <div class="product__price">${priceHTML(p)}</div>
        </div>
        ${swatches}
      </article>
    `;
  }

  function renderProducts(filter = 'all') {
    const list = filter === 'all' ? products : products.filter(p => p.filter === filter);
    grid.innerHTML = list.map(cardHTML).join('');
  }
  renderProducts();

  /* ---------- Tabs / filtering ---------- */
  document.getElementById('featuredTabs').addEventListener('click', (e) => {
    const t = e.target.closest('.tab');
    if (!t) return;
    document.querySelectorAll('#featuredTabs .tab').forEach(x => x.classList.remove('is-active'));
    t.classList.add('is-active');
    renderProducts(t.dataset.filter);
