    cartCount++;
    cartCountEl.textContent = cartCount;
    cartCountEl.classList.add('is-visible');
    cartCountEl.animate(
      [{ transform: 'scale(1.4)' }, { transform: 'scale(1)' }],
      { duration: 250, easing: 'ease-out' }
    );
