    d: document.getElementById('cdDays'),
    h: document.getElementById('cdHours'),
    m: document.getElementById('cdMins'),
    s: document.getElementById('cdSecs')
  };
  const pad = n => String(Math.max(0, n)).padStart(2, '0');
  function tick() {
    const diff = target - new Date();
    if (diff <= 0) { cd.d.textContent = cd.h.textContent = cd.m.textContent = cd.s.textContent = '00'; return; }
    const days = Math.floor(diff / 86400000);
    const hrs = Math.floor((diff / 3600000) % 24);
    const min = Math.floor((diff / 60000) % 60);
    const sec = Math.floor((diff / 1000) % 60);
    cd.d.textContent = pad(days);
    cd.h.textContent = pad(hrs);
    cd.m.textContent = pad(min);
    cd.s.textContent = pad(sec);
  }
  tick();
  setInterval(tick, 1000);

  /* ---------- Newsletter ---------- */
  const form = document.getElementById('newsletterForm');
  const msg = document.getElementById('newsletterMsg');
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const input = form.querySelector('input');
    if (!input.value || !/^\S+@\S+\.\S+$/.test(input.value)) {
      msg.textContent = 'Please enter a valid email.';
      msg.style.color = '#c2410c';
      return;
    }
    msg.textContent = `Welcome aboard — check ${input.value} for your code.`;
    msg.style.color = '';
    input.value = '';
    toast('Subscribed! 10% off coming your way.');
  });

  /* ---------- Reveal on scroll ---------- */
  const io = new IntersectionObserver((entries) => {
    entries.forEach(en => {
      if (en.isIntersecting) {
        en.target.style.animation = 'fadeUp .6s cubic-bezier(.2,.7,.2,1) both';
        io.unobserve(en.target);
      }
    });
  }, { rootMargin: '0px 0px -10% 0px', threshold: 0.05 });
  document.querySelectorAll('.section__head, .deal, .story, .value, .cat-card').forEach(el => io.observe(el));
})();
